macro_rules! impl_96 {
    () => {
        deps!();
        impl < 'a > Compiler < 'a > { fn new (builder : & 'a Builder) -> Result < Compiler < 'a > , BuildError > { let prefilter = prefilter :: Builder :: new (builder . match_kind) . ascii_case_insensitive (builder . ascii_case_insensitive) ; Ok (Compiler { builder , prefilter , nfa : NFA { match_kind : builder . match_kind , states : vec ! [] , sparse : vec ! [] , dense : vec ! [] , matches : vec ! [] , pattern_lens : vec ! [] , prefilter : None , byte_classes : ByteClasses :: singletons () , min_pattern_len : usize :: MAX , max_pattern_len : 0 , special : Special :: zero () , } , byteset : ByteClassSet :: empty () , }) } fn compile < I , P > (mut self , patterns : I) -> Result < NFA , BuildError > where I : IntoIterator < Item = P > , P : AsRef < [u8] > , { self . nfa . sparse . push (Transition :: default ()) ; self . nfa . matches . push (Match :: default ()) ; self . nfa . dense . push (NFA :: DEAD) ; self . nfa . alloc_state (0) ? ; self . nfa . alloc_state (0) ? ; self . nfa . special . start_unanchored_id = self . nfa . alloc_state (0) ? ; self . nfa . special . start_anchored_id = self . nfa . alloc_state (0) ? ; self . init_unanchored_start_state () ? ; self . add_dead_state_loop () ? ; self . build_trie (patterns) ? ; self . nfa . states . shrink_to_fit () ; self . nfa . byte_classes = self . byteset . byte_classes () ; self . set_anchored_start_state () ? ; self . add_unanchored_start_state_loop () ; self . densify () ? ; self . fill_failure_transitions () ? ; self . close_start_state_loop_for_leftmost () ; self . shuffle () ; self . nfa . prefilter = self . prefilter . build () ; self . nfa . special . max_special_id = if self . nfa . prefilter . is_some () { self . nfa . special . start_anchored_id } else { self . nfa . special . max_match_id } ; self . nfa . sparse . shrink_to_fit () ; self . nfa . dense . shrink_to_fit () ; self . nfa . matches . shrink_to_fit () ; self . nfa . pattern_lens . shrink_to_fit () ; Ok (self . nfa) } # [doc = " This sets up the initial prefix trie that makes up the Aho-Corasick"] # [doc = " automaton. Effectively, it creates the basic structure of the"] # [doc = " automaton, where every pattern given has a path from the start state to"] # [doc = " the end of the pattern."] fn build_trie < I , P > (& mut self , patterns : I) -> Result < () , BuildError > where I : IntoIterator < Item = P > , P : AsRef < [u8] > , { 'PATTERNS : for (i , pat) in patterns . into_iter () . enumerate () { let pid = PatternID :: new (i) . map_err (| e | { BuildError :: pattern_id_overflow (PatternID :: MAX . as_u64 () , e . attempted () ,) }) ? ; let pat = pat . as_ref () ; let patlen = SmallIndex :: new (pat . len ()) . map_err (| _ | BuildError :: pattern_too_long (pid , pat . len ())) ? ; self . nfa . min_pattern_len = core :: cmp :: min (self . nfa . min_pattern_len , pat . len ()) ; self . nfa . max_pattern_len = core :: cmp :: max (self . nfa . max_pattern_len , pat . len ()) ; assert_eq ! (i , self . nfa . pattern_lens . len () , "expected number of patterns to match pattern ID") ; self . nfa . pattern_lens . push (patlen) ; if self . builder . prefilter { self . prefilter . add (pat) ; } let mut prev = self . nfa . special . start_unanchored_id ; let mut saw_match = false ; for (depth , & b) in pat . iter () . enumerate () { saw_match = saw_match || self . nfa . states [prev] . is_match () ; if self . builder . match_kind . is_leftmost_first () && saw_match { continue 'PATTERNS ; } self . byteset . set_range (b , b) ; if self . builder . ascii_case_insensitive { let b = opposite_ascii_case (b) ; self . byteset . set_range (b , b) ; } let next = self . nfa . follow_transition (prev , b) ; if next != NFA :: FAIL { prev = next ; } else { let next = self . nfa . alloc_state (depth) ? ; self . nfa . add_transition (prev , b , next) ? ; if self . builder . ascii_case_insensitive { let b = opposite_ascii_case (b) ; self . nfa . add_transition (prev , b , next) ? ; } prev = next ; } } self . nfa . add_match (prev , pid) ? ; } Ok (()) } # [doc = " This routine creates failure transitions according to the standard"] # [doc = " textbook formulation of the Aho-Corasick algorithm, with a couple small"] # [doc = " tweaks to support \"leftmost\" semantics."] # [doc = ""] # [doc = " Building failure transitions is the most interesting part of building"] # [doc = " the Aho-Corasick automaton, because they are what allow searches to"] # [doc = " be performed in linear time. Specifically, a failure transition is"] # [doc = " a single transition associated with each state that points back to"] # [doc = " the longest proper suffix of the pattern being searched. The failure"] # [doc = " transition is followed whenever there exists no transition on the"] # [doc = " current state for the current input byte. If there is no other proper"] # [doc = " suffix, then the failure transition points back to the starting state."] # [doc = ""] # [doc = " For example, let's say we built an Aho-Corasick automaton with the"] # [doc = " following patterns: 'abcd' and 'cef'. The trie looks like this:"] # [doc = ""] # [doc = " ```ignore"] # [doc = "          a - S1 - b - S2 - c - S3 - d - S4*"] # [doc = "         /"] # [doc = "     S0 - c - S5 - e - S6 - f - S7*"] # [doc = " ```"] # [doc = ""] # [doc = " At this point, it should be fairly straight-forward to see how this"] # [doc = " trie can be used in a simplistic way. At any given position in the"] # [doc = " text we're searching (called the \"subject\" string), all we need to do"] # [doc = " is follow the transitions in the trie by consuming one transition for"] # [doc = " each byte in the subject string. If we reach a match state, then we can"] # [doc = " report that location as a match."] # [doc = ""] # [doc = " The trick comes when searching a subject string like 'abcef'. We'll"] # [doc = " initially follow the transition from S0 to S1 and wind up in S3 after"] # [doc = " observng the 'c' byte. At this point, the next byte is 'e' but state"] # [doc = " S3 has no transition for 'e', so the search fails. We then would need"] # [doc = " to restart the search at the next position in 'abcef', which"] # [doc = " corresponds to 'b'. The match would fail, but the next search starting"] # [doc = " at 'c' would finally succeed. The problem with this approach is that"] # [doc = " we wind up searching the subject string potentially many times. In"] # [doc = " effect, this makes the algorithm have worst case `O(n * m)` complexity,"] # [doc = " where `n ~ len(subject)` and `m ~ len(all patterns)`. We would instead"] # [doc = " like to achieve a `O(n + m)` worst case complexity."] # [doc = ""] # [doc = " This is where failure transitions come in. Instead of dying at S3 in"] # [doc = " the first search, the automaton can instruct the search to move to"] # [doc = " another part of the automaton that corresponds to a suffix of what"] # [doc = " we've seen so far. Recall that we've seen 'abc' in the subject string,"] # [doc = " and the automaton does indeed have a non-empty suffix, 'c', that could"] # [doc = " potentially lead to another match. Thus, the actual Aho-Corasick"] # [doc = " automaton for our patterns in this case looks like this:"] # [doc = ""] # [doc = " ```ignore"] # [doc = "          a - S1 - b - S2 - c - S3 - d - S4*"] # [doc = "         /                      /"] # [doc = "        /       ----------------"] # [doc = "       /       /"] # [doc = "     S0 - c - S5 - e - S6 - f - S7*"] # [doc = " ```"] # [doc = ""] # [doc = " That is, we have a failure transition from S3 to S5, which is followed"] # [doc = " exactly in cases when we are in state S3 but see any byte other than"] # [doc = " 'd' (that is, we've \"failed\" to find a match in this portion of our"] # [doc = " trie). We know we can transition back to S5 because we've already seen"] # [doc = " a 'c' byte, so we don't need to re-scan it. We can then pick back up"] # [doc = " with the search starting at S5 and complete our match."] # [doc = ""] # [doc = " Adding failure transitions to a trie is fairly simple, but subtle. The"] # [doc = " key issue is that you might have multiple failure transition that you"] # [doc = " need to follow. For example, look at the trie for the patterns"] # [doc = " 'abcd', 'b', 'bcd' and 'cd':"] # [doc = ""] # [doc = " ```ignore"] # [doc = "          - a - S1 - b - S2* - c - S3 - d - S4*"] # [doc = "         /               /         /"] # [doc = "        /         -------   -------"] # [doc = "       /         /         /"] # [doc = "     S0 --- b - S5* - c - S6 - d - S7*"] # [doc = "       \\                  /"] # [doc = "        \\         --------"] # [doc = "         \\       /"] # [doc = "          - c - S8 - d - S9*"] # [doc = " ```"] # [doc = ""] # [doc = " The failure transitions for this trie are defined from S2 to S5,"] # [doc = " S3 to S6 and S6 to S8. Moreover, state S2 needs to track that it"] # [doc = " corresponds to a match, since its failure transition to S5 is itself"] # [doc = " a match state."] # [doc = ""] # [doc = " Perhaps simplest way to think about adding these failure transitions"] # [doc = " is recursively. That is, if you know the failure transitions for every"] # [doc = " possible previous state that could be visited (e.g., when computing the"] # [doc = " failure transition for S3, you already know the failure transitions"] # [doc = " for S0, S1 and S2), then you can simply follow the failure transition"] # [doc = " of the previous state and check whether the incoming transition is"] # [doc = " defined after following the failure transition."] # [doc = ""] # [doc = " For example, when determining the failure state for S3, by our"] # [doc = " assumptions, we already know that there is a failure transition from"] # [doc = " S2 (the previous state) to S5. So we follow that transition and check"] # [doc = " whether the transition connecting S2 to S3 is defined. Indeed, it is,"] # [doc = " as there is a transition from S5 to S6 for the byte 'c'. If no such"] # [doc = " transition existed, we could keep following the failure transitions"] # [doc = " until we reach the start state, which is the failure transition for"] # [doc = " every state that has no corresponding proper suffix."] # [doc = ""] # [doc = " We don't actually use recursion to implement this, but instead, use a"] # [doc = " breadth first search of the automaton. Our base case is the start"] # [doc = " state, whose failure transition is just a transition to itself."] # [doc = ""] # [doc = " When building a leftmost automaton, we proceed as above, but only"] # [doc = " include a subset of failure transitions. Namely, we omit any failure"] # [doc = " transitions that appear after a match state in the trie. This is"] # [doc = " because failure transitions always point back to a proper suffix of"] # [doc = " what has been seen so far. Thus, following a failure transition after"] # [doc = " a match implies looking for a match that starts after the one that has"] # [doc = " already been seen, which is of course therefore not the leftmost match."] # [doc = ""] # [doc = " N.B. I came up with this algorithm on my own, and after scouring all of"] # [doc = " the other AC implementations I know of (Perl, Snort, many on GitHub)."] # [doc = " I couldn't find any that implement leftmost semantics like this."] # [doc = " Perl of course needs leftmost-first semantics, but they implement it"] # [doc = " with a seeming hack at *search* time instead of encoding it into the"] # [doc = " automaton. There are also a couple Java libraries that support leftmost"] # [doc = " longest semantics, but they do it by building a queue of matches at"] # [doc = " search time, which is even worse than what Perl is doing. ---AG"] fn fill_failure_transitions (& mut self) -> Result < () , BuildError > { let is_leftmost = self . builder . match_kind . is_leftmost () ; let start_uid = self . nfa . special . start_unanchored_id ; let mut queue = VecDeque :: new () ; let mut seen = self . queued_set () ; let mut prev_link = None ; while let Some (link) = self . nfa . next_link (start_uid , prev_link) { prev_link = Some (link) ; let t = self . nfa . sparse [link] ; if start_uid == t . next () || seen . contains (t . next) { continue ; } queue . push_back (t . next) ; seen . insert (t . next) ; if is_leftmost && self . nfa . states [t . next] . is_match () { self . nfa . states [t . next] . fail = NFA :: DEAD ; } } while let Some (id) = queue . pop_front () { let mut prev_link = None ; while let Some (link) = self . nfa . next_link (id , prev_link) { prev_link = Some (link) ; let t = self . nfa . sparse [link] ; if seen . contains (t . next) { continue ; } queue . push_back (t . next) ; seen . insert (t . next) ; if is_leftmost && self . nfa . states [t . next] . is_match () { self . nfa . states [t . next] . fail = NFA :: DEAD ; continue ; } let mut fail = self . nfa . states [id] . fail ; while self . nfa . follow_transition (fail , t . byte) == NFA :: FAIL { fail = self . nfa . states [fail] . fail ; } fail = self . nfa . follow_transition (fail , t . byte) ; self . nfa . states [t . next] . fail = fail ; self . nfa . copy_matches (fail , t . next) ? ; } if ! is_leftmost { self . nfa . copy_matches (self . nfa . special . start_unanchored_id , id) ? ; } } Ok (()) } # [doc = " Shuffle the states so that they appear in this sequence:"] # [doc = ""] # [doc = "   DEAD, FAIL, MATCH..., START, START, NON-MATCH..."] # [doc = ""] # [doc = " The idea here is that if we know how special states are laid out in our"] # [doc = " transition table, then we can determine what \"kind\" of state we're in"] # [doc = " just by comparing our current state ID with a particular value. In this"] # [doc = " way, we avoid doing extra memory lookups."] # [doc = ""] # [doc = " Before shuffling begins, our states look something like this:"] # [doc = ""] # [doc = "   DEAD, FAIL, START, START, (MATCH | NON-MATCH)..."] # [doc = ""] # [doc = " So all we need to do is move all of the MATCH states so that they"] # [doc = " all appear before any NON-MATCH state, like so:"] # [doc = ""] # [doc = "   DEAD, FAIL, START, START, MATCH... NON-MATCH..."] # [doc = ""] # [doc = " Then it's just a simple matter of swapping the two START states with"] # [doc = " the last two MATCH states."] # [doc = ""] # [doc = " (This is the same technique used for fully compiled DFAs in"] # [doc = " regex-automata.)"] fn shuffle (& mut self) { let old_start_uid = self . nfa . special . start_unanchored_id ; let old_start_aid = self . nfa . special . start_anchored_id ; assert ! (old_start_uid < old_start_aid) ; assert_eq ! (3 , old_start_aid . as_usize () , "anchored start state should be at index 3") ; let mut remapper = Remapper :: new (& self . nfa , 0) ; let mut next_avail = StateID :: from (4u8) ; for i in next_avail . as_usize () .. self . nfa . states . len () { let sid = StateID :: new (i) . unwrap () ; if ! self . nfa . states [sid] . is_match () { continue ; } remapper . swap (& mut self . nfa , sid , next_avail) ; next_avail = StateID :: new (next_avail . one_more ()) . unwrap () ; } let new_start_aid = StateID :: new (next_avail . as_usize () . checked_sub (1) . unwrap ()) . unwrap () ; remapper . swap (& mut self . nfa , old_start_aid , new_start_aid) ; let new_start_uid = StateID :: new (next_avail . as_usize () . checked_sub (2) . unwrap ()) . unwrap () ; remapper . swap (& mut self . nfa , old_start_uid , new_start_uid) ; let new_max_match_id = StateID :: new (next_avail . as_usize () . checked_sub (3) . unwrap ()) . unwrap () ; self . nfa . special . max_match_id = new_max_match_id ; self . nfa . special . start_unanchored_id = new_start_uid ; self . nfa . special . start_anchored_id = new_start_aid ; if self . nfa . states [self . nfa . special . start_anchored_id] . is_match () { self . nfa . special . max_match_id = self . nfa . special . start_anchored_id ; } remapper . remap (& mut self . nfa) ; } # [doc = " Attempts to convert the transition representation of a subset of states"] # [doc = " in this NFA from sparse to dense. This can greatly improve search"] # [doc = " performance since states with a higher number of transitions tend to"] # [doc = " correlate with very active states."] # [doc = ""] # [doc = " We generally only densify states that are close to the start state."] # [doc = " These tend to be the most active states and thus benefit from a dense"] # [doc = " representation more than other states."] # [doc = ""] # [doc = " This tends to best balance between memory usage and performance. In"] # [doc = " particular, the *vast majority* of all states in a typical Aho-Corasick"] # [doc = " automaton have only 1 transition and are usually farther from the start"] # [doc = " state and thus don't get densified."] # [doc = ""] # [doc = " Note that this doesn't remove the sparse representation of transitions"] # [doc = " for states that are densified. It could be done, but actually removing"] # [doc = " entries from `NFA::sparse` is likely more expensive than it's worth."] fn densify (& mut self) -> Result < () , BuildError > { for i in 0 .. self . nfa . states . len () { let sid = StateID :: new (i) . unwrap () ; if sid == NFA :: DEAD || sid == NFA :: FAIL { continue ; } if self . nfa . states [sid] . depth . as_usize () >= self . builder . dense_depth { continue ; } let dense = self . nfa . alloc_dense_state () ? ; let mut prev_link = None ; while let Some (link) = self . nfa . next_link (sid , prev_link) { prev_link = Some (link) ; let t = self . nfa . sparse [link] ; let class = usize :: from (self . nfa . byte_classes . get (t . byte)) ; let index = dense . as_usize () + class ; self . nfa . dense [index] = t . next ; } self . nfa . states [sid] . dense = dense ; } Ok (()) } # [doc = " Returns a set that tracked queued states."] # [doc = ""] # [doc = " This is only necessary when ASCII case insensitivity is enabled, since"] # [doc = " it is the only way to visit the same state twice. Otherwise, this"] # [doc = " returns an inert set that nevers adds anything and always reports"] # [doc = " `false` for every member test."] fn queued_set (& self) -> QueuedSet { if self . builder . ascii_case_insensitive { QueuedSet :: active () } else { QueuedSet :: inert () } } # [doc = " Initializes the unanchored start state by making it dense. This is"] # [doc = " achieved by explicitly setting every transition to the FAIL state."] # [doc = " This isn't necessary for correctness, since any missing transition is"] # [doc = " automatically assumed to be mapped to the FAIL state. We do this to"] # [doc = " make the unanchored starting state dense, and thus in turn make"] # [doc = " transition lookups on it faster. (Which is worth doing because it's"] # [doc = " the most active state.)"] fn init_unanchored_start_state (& mut self) -> Result < () , BuildError > { let start_uid = self . nfa . special . start_unanchored_id ; let start_aid = self . nfa . special . start_anchored_id ; self . nfa . init_full_state (start_uid , NFA :: FAIL) ? ; self . nfa . init_full_state (start_aid , NFA :: FAIL) ? ; Ok (()) } # [doc = " Setup the anchored start state by copying all of the transitions and"] # [doc = " matches from the unanchored starting state with one change: the failure"] # [doc = " transition is changed to the DEAD state, so that for any undefined"] # [doc = " transitions, the search will stop."] fn set_anchored_start_state (& mut self) -> Result < () , BuildError > { let start_uid = self . nfa . special . start_unanchored_id ; let start_aid = self . nfa . special . start_anchored_id ; let (mut uprev_link , mut aprev_link) = (None , None) ; loop { let unext = self . nfa . next_link (start_uid , uprev_link) ; let anext = self . nfa . next_link (start_aid , aprev_link) ; let (ulink , alink) = match (unext , anext) { (Some (ulink) , Some (alink)) => (ulink , alink) , (None , None) => break , _ => unreachable ! () , } ; uprev_link = Some (ulink) ; aprev_link = Some (alink) ; self . nfa . sparse [alink] . next = self . nfa . sparse [ulink] . next ; } self . nfa . copy_matches (start_uid , start_aid) ? ; self . nfa . states [start_aid] . fail = NFA :: DEAD ; Ok (()) } # [doc = " Set the failure transitions on the start state to loop back to the"] # [doc = " start state. This effectively permits the Aho-Corasick automaton to"] # [doc = " match at any position. This is also required for finding the next"] # [doc = " state to terminate, namely, finding the next state should never return"] # [doc = " a fail_id."] # [doc = ""] # [doc = " This must be done after building the initial trie, since trie"] # [doc = " construction depends on transitions to `fail_id` to determine whether a"] # [doc = " state already exists or not."] fn add_unanchored_start_state_loop (& mut self) { let start_uid = self . nfa . special . start_unanchored_id ; let mut prev_link = None ; while let Some (link) = self . nfa . next_link (start_uid , prev_link) { prev_link = Some (link) ; if self . nfa . sparse [link] . next () == NFA :: FAIL { self . nfa . sparse [link] . next = start_uid ; } } } # [doc = " Remove the start state loop by rewriting any transitions on the start"] # [doc = " state back to the start state with transitions to the dead state."] # [doc = ""] # [doc = " The loop is only closed when two conditions are met: the start state"] # [doc = " is a match state and the match kind is leftmost-first or"] # [doc = " leftmost-longest."] # [doc = ""] # [doc = " The reason for this is that under leftmost semantics, a start state"] # [doc = " that is also a match implies that we should never restart the search"] # [doc = " process. We allow normal transitions out of the start state, but if"] # [doc = " none exist, we transition to the dead state, which signals that"] # [doc = " searching should stop."] fn close_start_state_loop_for_leftmost (& mut self) { let start_uid = self . nfa . special . start_unanchored_id ; let start = & mut self . nfa . states [start_uid] ; let dense = start . dense ; if self . builder . match_kind . is_leftmost () && start . is_match () { let mut prev_link = None ; while let Some (link) = self . nfa . next_link (start_uid , prev_link) { prev_link = Some (link) ; if self . nfa . sparse [link] . next () == start_uid { self . nfa . sparse [link] . next = NFA :: DEAD ; if dense != StateID :: ZERO { let b = self . nfa . sparse [link] . byte ; let class = usize :: from (self . nfa . byte_classes . get (b)) ; self . nfa . dense [dense . as_usize () + class] = NFA :: DEAD ; } } } } } # [doc = " Sets all transitions on the dead state to point back to the dead state."] # [doc = " Normally, missing transitions map back to the failure state, but the"] # [doc = " point of the dead state is to act as a sink that can never be escaped."] fn add_dead_state_loop (& mut self) -> Result < () , BuildError > { self . nfa . init_full_state (NFA :: DEAD , NFA :: DEAD) ? ; Ok (()) } }
    };
}

